"""rad0037 (VTP43): --kv-cache-dtype bf16_fp8, a paged KV cache of bf16 keys and E4M3 values
(3 * head_dim bytes a token and head against 4 * head_dim bf16 and 2 * head_dim fp8), served by
libr4d's h256/gqa6 prefill and decode kernels (option O_KB16V8), a store, and the fused
qk_norm_rope_gate store. The ABI names it RAD_KVQ_B16F8; the Qwen3.5 FP8 plugin declares it.
"""
from __future__ import annotations

import re
from bigcherry.patcher import Edit, FilePatch


def _edit(id: str, before: str, after: str, guard: str) -> Edit:
    span = max(4, before.count("\n") + 2)
    return Edit(id=id, anchor=re.escape(before), mode="replace", text=after,
                guard=re.escape(guard), expect_matches=1, max_span_lines=span,
                rationale=("long-anchor: the whole diff hunk is the anchor; " if span > 6 else "")
                + "VTP43: bf16_fp8 KV cache")


