    FilePatch(path='tests/arch_test.cpp', language="none", description='VTP43 card-free engine tests', edits=(
        _edit('arch_test_cpp-0', '    RadArchProbe p{};\n    CHECK_OK(qwen35_fp8::probe(mk.meta(), &p));\n    CHECK_EQ(p.control_vector_ok, 0);\n    CHECK_EQ(p.kv_quant_ok, (1 << RAD_KVQ_V4) | (1 << RAD_KVQ_K6V4));\n}\n\n/* --kv-cache-dtype k6_v4: int6 K and int4 V, each in groups of 32 with an f16 scale, 352 bytes a\n', '    RadArchProbe p{};\n    CHECK_OK(qwen35_fp8::probe(mk.meta(), &p));\n    CHECK_EQ(p.control_vector_ok, 0);\n    CHECK_EQ(p.kv_quant_ok, (1 << RAD_KVQ_V4) | (1 << RAD_KVQ_K6V4) | (1 << RAD_KVQ_B16F8));\n}\n\n/* --kv-cache-dtype k6_v4: int6 K and int4 V, each in groups of 32 with an f16 scale, 352 bytes a\n', 'CHECK_EQ(p.kv_quant_ok, (1 << RAD_KVQ_V4) | (1 << RAD_KVQ_K6V4) | (1 << RAD_KVQ_B16F8));'),
        _edit('arch_test_cpp-1', '    CHECK(noted(b, "kv cache k6_v4"));\n}\n\n/* A packed KV cache declares no streamed store and no fold. libr4d\'s streamed rows are the E4M3 and\n * bf16 ones only (libr4d/r4d_rows.cpp), and both streamed ops are weightless, so a declaration with\n * no row for the layout is a device band that resolved to nothing -- a hole, which refuses startup\n', '    CHECK(noted(b, "kv cache k6_v4"));\n}\n\n/* --kv-cache-dtype bf16_fp8: bf16 K (512 bytes) and E4M3 V (256), 768 bytes a token and head,\n * declared as 48 * 256 / 32 = 384 E4M3 columns; the trunk\'s ops band on kv_dtype bf16_fp8 and the\n * drafter\'s group stays E4M3. */\nTEST(qwen35_fp8_bf16_fp8_cache_is_768_bytes_a_token_and_head) {\n    MetaKV mk = with_dflash2(q35fp8_meta());\n    RadBuilder b;\n    RadBuildCtx ctx = spec_ctx(0, 1, 7);\n    ctx.kv_dtype = RAD_F8E4M3;\n    ctx.kv_quant = RAD_KVQ_B16F8;\n    REQUIRE_EQ(qwen35_fp8::declare(&b, mk.meta(), &ctx), RAD_OK);\n    const RadKVGroupDecl& f = b.kv_groups[0].d;\n    CHECK_EQ(f.dtype, (uint32_t)RAD_F8E4M3);\n    CHECK_EQ(f.head_dim, 384);           /* 2 * 384 = 768 bytes a token and head */\n    CHECK_EQ(b.kv_groups.back().d.head_dim, 128);\n    int bf = 0, other = 0, e4 = 0;\n    for (const auto& o : b.ops) {\n        const std::string kd = pstr(&o, "kv_dtype");\n        bf += kd == "bf16_fp8"; e4 += kd == "fp8_e4m3";\n        other += kd == "fp8_v4" || kd == "k6_v4";\n    }\n    CHECK(bf > 0);\n    CHECK(e4 > 0);                       /* the drafter\'s attention */\n    CHECK_EQ(other, 0);\n    CHECK(noted(b, "kv cache bf16_fp8"));\n}\n\n/* A packed KV cache declares no streamed store and no fold. libr4d\'s streamed rows are the E4M3 and\n * bf16 ones only (libr4d/r4d_rows.cpp), and both streamed ops are weightless, so a declaration with\n * no row for the layout is a device band that resolved to nothing -- a hole, which refuses startup\n', '/* --kv-cache-dtype bf16_fp8: bf16 K (512 bytes) and E4M3 V (256), 768 bytes a token and head,'),
        _edit('arch_test_cpp-2', '\n    /* Over the fp8_v4 and k6_v4 layouts the trunk\'s attention states it beside the layout\'s\n     * kv_dtype, which is what libr4d\'s legs for those caches match. */\n    for (int kvq : { (int)RAD_KVQ_V4, (int)RAD_KVQ_K6V4 }) {\n        RadBuilder q;\n        RadBuildCtx cq = spec_ctx(0, 1, 7);\n        cq.kv_dtype = RAD_F8E4M3;\n        cq.kv_quant = kvq;\n        cq.attn_prefill_fp8 = RAD_ATTN_FP8_PV;\n        REQUIRE_EQ(qwen35_fp8::declare(&q, mk.meta(), &cq), RAD_OK);\n        const std::string want = kvq == RAD_KVQ_V4 ? "fp8_v4" : "k6_v4";\n        int legs = 0;\n        for (const auto& o : q.ops) {\n            const RecParam* p = param(&o, "prefill_fp8");\n', '\n    /* Over the fp8_v4 and k6_v4 layouts the trunk\'s attention states it beside the layout\'s\n     * kv_dtype, which is what libr4d\'s legs for those caches match. */\n    for (int kvq : { (int)RAD_KVQ_V4, (int)RAD_KVQ_K6V4, (int)RAD_KVQ_B16F8 }) {\n        RadBuilder q;\n        RadBuildCtx cq = spec_ctx(0, 1, 7);\n        cq.kv_dtype = RAD_F8E4M3;\n        cq.kv_quant = kvq;\n        cq.attn_prefill_fp8 = RAD_ATTN_FP8_PV;\n        REQUIRE_EQ(qwen35_fp8::declare(&q, mk.meta(), &cq), RAD_OK);\n        const std::string want = kvq == RAD_KVQ_V4 ? "fp8_v4" : kvq == RAD_KVQ_K6V4 ? "k6_v4" : "bf16_fp8";\n        int legs = 0;\n        for (const auto& o : q.ops) {\n            const RecParam* p = param(&o, "prefill_fp8");\n', 'for (int kvq : { (int)RAD_KVQ_V4, (int)RAD_KVQ_K6V4, (int)RAD_KVQ_B16F8 }) {'),
        _edit('arch_test_cpp-3', '    RadArchProbe p{};\n    CHECK_OK(qwen35_fp8::probe(mk.meta(), &p));\n    CHECK_EQ(p.kv_quant_ok, 0);\n    for (int q : { (int)RAD_KVQ_V4, (int)RAD_KVQ_K6V4 }) {\n        RadBuilder b;\n        RadBuildCtx ctx = build_ctx();\n        ctx.kv_dtype = RAD_F8E4M3;\n', '    RadArchProbe p{};\n    CHECK_OK(qwen35_fp8::probe(mk.meta(), &p));\n    CHECK_EQ(p.kv_quant_ok, 0);\n    for (int q : { (int)RAD_KVQ_V4, (int)RAD_KVQ_K6V4, (int)RAD_KVQ_B16F8 }) {\n        RadBuilder b;\n        RadBuildCtx ctx = build_ctx();\n        ctx.kv_dtype = RAD_F8E4M3;\n', 'for (int q : { (int)RAD_KVQ_V4, (int)RAD_KVQ_K6V4, (int)RAD_KVQ_B16F8 }) {'),
    )),
    FilePatch(path='tests/config_test.cpp', language="none", description='VTP43 card-free engine tests', edits=(
        _edit('config_test_cpp-0', '    CHECK_EQ(parse({ "--state-cache-dtype" }, &c), RAD_E_INVAL);\n}\n\nTEST(the_kv_cache_dtype_is_one_of_four_names) {\n    Config c;\n    CHECK_EQ(parse({ "--kv-cache-dtype", "bf16" }, &c), RAD_OK);\n    CHECK_EQ(c.kv_cache_dtype, std::string("bf16"));\n', '    CHECK_EQ(parse({ "--state-cache-dtype" }, &c), RAD_E_INVAL);\n}\n\nTEST(the_kv_cache_dtype_is_one_of_five_names) {\n    Config c;\n    CHECK_EQ(parse({ "--kv-cache-dtype", "bf16" }, &c), RAD_OK);\n    CHECK_EQ(c.kv_cache_dtype, std::string("bf16"));\n', 'TEST(the_kv_cache_dtype_is_one_of_five_names) {'),
        _edit('config_test_cpp-1', '    CHECK_EQ(c.kv_cache_dtype, std::string("fp8_v4"));\n    CHECK_EQ(parse({ "--kv-cache-dtype", "k6_v4" }, &c), RAD_OK);\n    CHECK_EQ(c.kv_cache_dtype, std::string("k6_v4"));\n    /* Four values only: an "auto" resolving to bf16 would be a second name for the default, and\n     * each value should be unambiguous in a log. */\n    CHECK_EQ(parse({ "--kv-cache-dtype", "auto" }, &c), RAD_E_INVAL);\n    CHECK_EQ(parse({ "--kv-cache-dtype", "fp16" }, &c), RAD_E_INVAL);\n', '    CHECK_EQ(c.kv_cache_dtype, std::string("fp8_v4"));\n    CHECK_EQ(parse({ "--kv-cache-dtype", "k6_v4" }, &c), RAD_OK);\n    CHECK_EQ(c.kv_cache_dtype, std::string("k6_v4"));\n    CHECK_EQ(parse({ "--kv-cache-dtype", "bf16_fp8" }, &c), RAD_OK);\n    CHECK_EQ(c.kv_cache_dtype, std::string("bf16_fp8"));\n    CHECK_EQ(bc_kv_quant_of("bf16_fp8"), (int)RAD_KVQ_B16F8);\n    CHECK_EQ(bc_kv_quant_of("fp8"), (int)RAD_KVQ_NONE);\n    /* Five values only: an "auto" resolving to bf16 would be a second name for the default, and\n     * each value should be unambiguous in a log. */\n    CHECK_EQ(parse({ "--kv-cache-dtype", "auto" }, &c), RAD_E_INVAL);\n    CHECK_EQ(parse({ "--kv-cache-dtype", "fp16" }, &c), RAD_E_INVAL);\n', 'CHECK_EQ(parse({ "--kv-cache-dtype", "bf16_fp8" }, &c), RAD_OK);'),
    )),
